static bool em_history_mean_variance(const SportCountAnalyzer *analyzer,
                                     const int16_t            *history,
                                     float                    *mean,
                                     float                    *variance) {
  float sum = 0.0f;
  float square_sum = 0.0f;
  int   i;

  for (i = 0; i < EM_HISTORY_SIZE; ++i) {
    const float value =
        em_history_value(history, analyzer->em->history_pos, i);
    if (!isfinite(value)) {
      return false;
    }
    sum += value;
  }
  *mean = sum / (float)EM_HISTORY_SIZE;
  for (i = 0; i < EM_HISTORY_SIZE; ++i) {
    const float centered =
        em_history_value(history, analyzer->em->history_pos, i) - *mean;
    square_sum += centered * centered;
  }
  *variance = square_sum / (float)EM_HISTORY_SIZE;
  return isfinite(*variance);
}

