static bool em_history_mean_variance(const SportCountAnalyzer *analyzer,
                                     const int16_t            *history,
                                     float                    *mean,
                                     float                    *variance) {
  /* 单遍求 mean 与 variance：Var(X) = E[X²] - (E[X])²。
   * 双精度累加避免 E[X²] 和 mean² 相近时的抵消损失；对 int16 解码
   * 后有界的信号，最终结果与两遍法数值一致到 float 末位。 */
  double sum = 0.0;
  double sum_sq = 0.0;
  int    i;

  for (i = 0; i < EM_HISTORY_SIZE; ++i) {
    const double value = (double)em_history_value(
        history, analyzer->em->history_pos, i);
    sum += value;
    sum_sq += value * value;
  }
  {
    const double m = sum / (double)EM_HISTORY_SIZE;
    const double var = sum_sq / (double)EM_HISTORY_SIZE - m * m;
    *mean = (float)m;
    *variance = (float)(var > 0.0 ? var : 0.0);
  }
  return isfinite(*mean) && isfinite(*variance);
}

