static void em_init_hann_tables(EmOnlineState *state) {
  const float denom_sym = (float)(EM_HISTORY_SIZE - 1);
  const float denom_per = (float)EM_HISTORY_SIZE;
  int i;
  for (i = 0; i < EM_HISTORY_SIZE; ++i) {
    const float phase = 2.0f * EM_PI * (float)i;
    state->hann_symmetric[i] = 0.5f - 0.5f * cosf(phase / denom_sym);
    state->hann_periodic[i]  = 0.5f - 0.5f * cosf(phase / denom_per);
  }
}

