static void em_dft_power(const SportCountAnalyzer *analyzer,
                         const int16_t            *history,
                         const float              *window,
                         float                     mean,
                         int                       nfft,
                         int                       bin,
                         float                    *power) {
  const float angle = -2.0f * EM_PI * (float)bin / (float)nfft;
  const float step_re = cosf(angle);
  const float step_im = sinf(angle);
  float       phase_re = 1.0f;
  float       phase_im = 0.0f;
  float       sum_re = 0.0f;
  float       sum_im = 0.0f;
  int         i;

  for (i = 0; i < EM_HISTORY_SIZE; ++i) {
    const float sample =
        (em_history_value(history, analyzer->em->history_pos, i) - mean) *
        window[i];
    const float next_re = phase_re * step_re - phase_im * step_im;
    const float next_im = phase_re * step_im + phase_im * step_re;
    sum_re += sample * phase_re;
    sum_im += sample * phase_im;
    phase_re = next_re;
    phase_im = next_im;
  }
  *power = sum_re * sum_re + sum_im * sum_im;
}

