/* Goertzel 算法计算单 bin |DFT|²。相比"每步维护复相位 (re, im)"的做法，
 * 内层从 6 mul + 4 add/sub 降到 1 mul + 2 add/sub。数学上等价：
 * 定义 y[i] = x[i] + coeff·y[i-1] − y[i-2]，其中 coeff = 2·cos(2π·bin/nfft)，
 * 处理 N 个样本后 y[N-1]、y[N-2] 编码了同一个 DFT 结果，功率闭式解：
 *   |X_k|² = y[N-1]² + y[N-2]² − coeff·y[N-1]·y[N-2]
 * 对零填充 DFT 同样成立（提前停止递推等价于后续输入置零）。 */
static void em_dft_power(const SportCountAnalyzer *analyzer,
                         const int16_t            *history,
                         const int16_t            *window,
                         float                     mean,
                         int                       nfft,
                         int                       bin,
                         float                    *power) {
  const float coeff =
      2.0f * cosf(2.0f * EM_PI * (float)bin / (float)nfft);
  float s_prev = 0.0f;
  float s_prev2 = 0.0f;
  int   i;

  for (i = 0; i < EM_HISTORY_SIZE; ++i) {
    const float w = (float)window[i] * EM_HANN_INV_Q15_SCALE;
    const float sample =
        (em_history_value(history, analyzer->em->history_pos, i) - mean) * w;
    const float s = sample + coeff * s_prev - s_prev2;
    s_prev2 = s_prev;
    s_prev = s;
  }
  *power = s_prev * s_prev + s_prev2 * s_prev2 - coeff * s_prev * s_prev2;
}

