// Copyright (c) Xiaomi. 2026. All rights reserved.
//
// 椭圆机（EM）计数算法单元测试。
//
// 测试策略：只走公共 API（analyzer_init / feed_data / feed_data_finished），
// 内部 static 函数（em_dft_power / em_history_encode / em_init_hann_tables 等）
// 不直接暴露，通过"端到端喂合成信号 + 检查输出"覆盖。
//
// 覆盖的关键优化点：
//   - Goertzel 算法数值等价性（喂纯正弦，验证 f0 估计正确）
//   - Hann Q15 量化容差（喂强信号，验证 conf 达标）
//   - uint8 环绕差分（连续喂 30+ 秒，验证 freq 输出合理）
//   - nfft=1024 峰值定位精度（不同频率的正弦）
//   - 资源生命周期（init / free 配对，valgrind 无泄漏）

#include <cmath>
#include <cstdint>
#include <vector>

#include "cyclic_sport_count_analyzer.h"
#include "gtest/gtest.h"

namespace {

constexpr float kPi = 3.14159265358979323846f;
constexpr float kGravity = 9.80665f;
constexpr int kSampleRateHz = 25;
constexpr uint8_t kSampleRateHzU8 = 25;

CyclicSportCountConfig MakeEmConfig() {
  CyclicSportCountConfig cfg = {};
  cfg.sport_type = MI_COUNT_ELLIPTICAL_MACHINE;
  cfg.data_freq_hz = kSampleRateHzU8;
  return cfg;
}

// 合成一段"椭圆机风格"加速度：竖直方向 base=g + amp·sin(2π·f·t)，
// 水平方向平稳、加少量白噪。这是走 acc_x 链路的干净场景。
CyclicSportCountResult FeedSineForSeconds(void* instance,
                                          float freq_hz,
                                          float amp,
                                          int seconds) {
  CyclicSportCountResult res = {};
  const int total = seconds * kSampleRateHz;
  for (int i = 0; i < total; ++i) {
    const float t = static_cast<float>(i) / kSampleRateHz;
    const float phase = 2.0f * kPi * freq_hz * t;
    const float dyn = amp * std::sin(phase);
    // acc_x 上承载周期分量，acc_y/z 上模拟接近重力的静态
    const float ax = dyn;
    const float ay = 0.1f;
    const float az = kGravity;
    res = cyclic_sport_count_feed_data(
        instance,
        static_cast<uint64_t>(i * 40),  // 25 Hz → 40 ms 间隔
        ax,
        ay,
        az);
  }
  return res;
}

// -- 基础生命周期 --------------------------------------------------------

TEST(EmAlgoLifecycle, InitAndFinishOnce) {
  void* instance = cyclic_sport_count_feed_data_init(MakeEmConfig());
  ASSERT_NE(instance, nullptr);
  const CyclicSportCountError err = cyclic_sport_feed_data_finished(instance);
  EXPECT_EQ(err, ERR_SPORT_COUNT_SUCCESS);
}

TEST(EmAlgoLifecycle, IdleSignalYieldsZeroCounter) {
  void* instance = cyclic_sport_count_feed_data_init(MakeEmConfig());
  ASSERT_NE(instance, nullptr);
  // 30 秒静止（重力为主），counter 应为 0
  CyclicSportCountResult res = {};
  const int total = 30 * kSampleRateHz;
  for (int i = 0; i < total; ++i) {
    res = cyclic_sport_count_feed_data(
        instance, static_cast<uint64_t>(i * 40), 0.01f, 0.01f, kGravity);
  }
  EXPECT_EQ(res.counter, 0U);
  cyclic_sport_feed_data_finished(instance);
}

// -- 计数正确性 ----------------------------------------------------------

// 喂 60 秒 1 Hz 正弦（每个周期 = 2 步），counter 应接近 60 × 2 = 120。
// nfft=1024 + Hann Q15 + Goertzel 组合下，f0=1 Hz 是搜索带 [0.35, 1.90] 里的
// 典型值，主链路（acc_x）应稳定检出。
TEST(EmAlgoCounting, SineOneHzYieldsExpectedCount) {
  void* instance = cyclic_sport_count_feed_data_init(MakeEmConfig());
  ASSERT_NE(instance, nullptr);
  const CyclicSportCountResult res = FeedSineForSeconds(
      instance, /*freq_hz=*/1.0f, /*amp=*/5.0f, /*seconds=*/60);
  // 60 个周期 × 2 步/周期 = 120，允许 ±20% 容差（起动瞬变会吃掉几个周期）
  const uint32_t expected = 120;
  EXPECT_GE(res.counter, static_cast<uint32_t>(expected * 0.80f))
      << "counter=" << res.counter << " expected~" << expected;
  EXPECT_LE(res.counter, static_cast<uint32_t>(expected * 1.20f))
      << "counter=" << res.counter << " expected~" << expected;
  cyclic_sport_feed_data_finished(instance);
}

TEST(EmAlgoCounting, SinePointFiveHzYieldsHalf) {
  void* instance = cyclic_sport_count_feed_data_init(MakeEmConfig());
  ASSERT_NE(instance, nullptr);
  const CyclicSportCountResult res = FeedSineForSeconds(
      instance, /*freq_hz=*/0.5f, /*amp=*/5.0f, /*seconds=*/60);
  // 60 秒 × 0.5 Hz × 2 = 60 步
  const uint32_t expected = 60;
  EXPECT_GE(res.counter, static_cast<uint32_t>(expected * 0.70f))
      << "counter=" << res.counter << " expected~" << expected;
  EXPECT_LE(res.counter, static_cast<uint32_t>(expected * 1.30f))
      << "counter=" << res.counter << " expected~" << expected;
  cyclic_sport_feed_data_finished(instance);
}

// -- 步频输出（公开步频窗口，10 秒滚动差分 + uint8 环绕）--------------

TEST(EmAlgoPublicFreq, EmergesAfterWarmup) {
  void* instance = cyclic_sport_count_feed_data_init(MakeEmConfig());
  ASSERT_NE(instance, nullptr);
  // 前 10 秒预热期 freq 应为 0，超过后应有非零值
  CyclicSportCountResult early = {};
  CyclicSportCountResult late = {};
  const int warmup = 9 * kSampleRateHz;
  const int total = 40 * kSampleRateHz;
  for (int i = 0; i < total; ++i) {
    const float t = static_cast<float>(i) / kSampleRateHz;
    const float ax = 5.0f * std::sin(2.0f * kPi * 1.0f * t);
    const CyclicSportCountResult r = cyclic_sport_count_feed_data(
        instance, static_cast<uint64_t>(i * 40), ax, 0.01f, kGravity);
    if (i == warmup) {
      early = r;
    }
    if (i == total - 1) {
      late = r;
    }
  }
  EXPECT_EQ(early.freq, 0U) << "warmup 期内 freq 应为 0";
  // 1 Hz 正弦 → 2 步/秒 → 120 步/分钟，允许 ±40% 容差
  EXPECT_GT(late.freq, 60U) << "稳态 freq 应显著大于 0: " << late.freq;
  EXPECT_LT(late.freq, 200U) << "稳态 freq 不应远超 1 Hz 对应值: " << late.freq;
  cyclic_sport_feed_data_finished(instance);
}

// -- 确定性 -------------------------------------------------------------

TEST(EmAlgoDeterminism, SameInputSameOutput) {
  const CyclicSportCountConfig cfg = MakeEmConfig();
  CyclicSportCountResult r1 = {};
  CyclicSportCountResult r2 = {};

  for (int trial = 0; trial < 2; ++trial) {
    void* instance = cyclic_sport_count_feed_data_init(cfg);
    ASSERT_NE(instance, nullptr);
    const int total = 30 * kSampleRateHz;
    CyclicSportCountResult r = {};
    for (int i = 0; i < total; ++i) {
      const float t = static_cast<float>(i) / kSampleRateHz;
      const float ax = 5.0f * std::sin(2.0f * kPi * 0.8f * t);
      r = cyclic_sport_count_feed_data(
          instance, static_cast<uint64_t>(i * 40), ax, 0.01f, kGravity);
    }
    if (trial == 0) {
      r1 = r;
    } else {
      r2 = r;
    }
    cyclic_sport_feed_data_finished(instance);
  }

  EXPECT_EQ(r1.counter, r2.counter);
  EXPECT_EQ(r1.cs_num, r2.cs_num);
  EXPECT_EQ(r1.freq, r2.freq);
}

// -- 空/边界输入 --------------------------------------------------------

TEST(EmAlgoBoundary, ZeroSamplesFreeSafely) {
  void* instance = cyclic_sport_count_feed_data_init(MakeEmConfig());
  ASSERT_NE(instance, nullptr);
  // 一个样本都不喂就直接 free，valgrind 下应无泄漏
  EXPECT_EQ(cyclic_sport_feed_data_finished(instance),
            ERR_SPORT_COUNT_SUCCESS);
}

TEST(EmAlgoBoundary, FinishNullPointer) {
  const CyclicSportCountError err = cyclic_sport_feed_data_finished(nullptr);
  EXPECT_NE(err, ERR_SPORT_COUNT_SUCCESS)
      << "free(NULL) 应返回错误码，不 crash";
}

}  // namespace

