/* baseline: 空可执行体，用来测算 crt0 + libc-nano 启动开销
 * 编译/链接 flags 必须与 probe.elf 完全一致，否则减法无意义 */
void _exit(int code) { (void)code; while (1) {} }
int  main(void)      { return 0; }

/* probe: 调用算法完整生命周期，逼出真实链接路径
 * 编译/链接 flags 必须与 baseline.elf 完全一致 */
#include <stddef.h>
#include <stdint.h>

#include "cyclic_sport_count_analyzer.h"
#include "mi_cyclic_sport_counter_type.h"

/* 把 common/platform 里的 generic_* 都 stub 掉 —— 用固定 heap 池模拟 malloc/free。
 * 简单 bump allocator（free 直接 nop）足够 probe 走完一次 init/feed/finish。 */
static uint8_t heap_pool[16384] __attribute__((aligned(8)));
static size_t  heap_used = 0;

void *generic_malloc(size_t size) {
  size_t aligned = (size + 7U) & ~(size_t)7U;
  void  *p;
  if (heap_used + aligned > sizeof(heap_pool)) return (void *)0;
  p = &heap_pool[heap_used];
  heap_used += aligned;
  return p;
}

void generic_free(void *p) { (void)p; }

void *generic_memset(void *dst, int v, size_t n) {
  uint8_t *d = (uint8_t *)dst;
  while (n--) *d++ = (uint8_t)v;
  return dst;
}

void *generic_memcpy(void *dst, const void *src, size_t n) {
  uint8_t       *d = (uint8_t *)dst;
  const uint8_t *s = (const uint8_t *)src;
  while (n--) *d++ = *s++;
  return dst;
}

/* 日志函数在算法里频繁调用，stub 成空实现 */
void generic_print_log(int level, const char *tag, const char *fmt, ...) {
  (void)level; (void)tag; (void)fmt;
}

/* 半主机退出 */
void _exit(int code) { (void)code; while (1) {} }

int main(void) {
  CyclicSportCountConfig cfg;
  void                  *inst;
  uint64_t               t;
  volatile uint32_t      sink = 0;  /* 防止编译器把整段过程优化掉 */

  cfg.sport_type   = MI_COUNT_ELLIPTICAL_MACHINE;
  cfg.data_freq_hz = 25;

  inst = cyclic_sport_count_feed_data_init(cfg);
  if (inst == (void *)0) return 1;

  /* 喂 60 秒合成正弦（0.6 Hz，模拟踏步节奏），触发算法所有分支 */
  for (t = 0; t < 60000U; t += 40U) {
    /* 近似 sinf(2π·0.6·t/1000) 用泰勒展开前两项，避免拉入 libm 的 sinf */
    float ts = (float)t / 1000.0f;
    float ph = 6.2831853f * 0.6f * ts;
    float ax = 0.5f * ph;   /* 简化：只要有变化的输入即可 */
    CyclicSportCountResult res =
        cyclic_sport_count_feed_data(inst, t, ax, 0.0f, 9.8f);
    sink ^= res.counter;
  }
  cyclic_sport_feed_data_finished(inst);
  return (int)(sink & 0x1);
}

