/* 验证：运行时 em_init_hann_tables 的表值 vs 生成的常量表，逐位对比 */
#include <math.h>
#include <stdint.h>
#include <stdio.h>

#define EM_HISTORY_SIZE (500)
#define EM_PI (3.14159265358979323846f)
#define EM_HANN_Q15_ONE (32767)

static int16_t rt_hann_symmetric[EM_HISTORY_SIZE];
static int16_t rt_hann_periodic[EM_HISTORY_SIZE];

/* 与 cyclic_sport_count_analyzer.c 中 em_init_hann_tables 完全一致的逻辑 */
static void em_init_hann_tables(void) {
  const float denom_sym = (float)(EM_HISTORY_SIZE - 1);
  const float denom_per = (float)EM_HISTORY_SIZE;
  const float scale = (float)EM_HANN_Q15_ONE;
  int i;
  for (i = 0; i < EM_HISTORY_SIZE; ++i) {
    const float phase = 2.0f * EM_PI * (float)i;
    const float sym = 0.5f - 0.5f * cosf(phase / denom_sym);
    const float per = 0.5f - 0.5f * cosf(phase / denom_per);
    rt_hann_symmetric[i] = (int16_t)(sym * scale + 0.5f);
    rt_hann_periodic[i] = (int16_t)(per * scale + 0.5f);
  }
}

/* 生成的常量表（来自 /tmp/hann_tables.inc） */
#include "/tmp/hann_tables.inc"

int main(void) {
  int mismatches = 0;
  int max_delta = 0;
  int i;

  em_init_hann_tables();

  for (i = 0; i < EM_HISTORY_SIZE; ++i) {
    if (rt_hann_symmetric[i] != hann_symmetric_q15[i]) {
      int d = (int)rt_hann_symmetric[i] - (int)hann_symmetric_q15[i];
      if (d < 0) d = -d;
      if (d > max_delta) max_delta = d;
      if (mismatches < 5)
        printf("sym[%d]: rt=%d gen=%d (delta %d)\n", i, rt_hann_symmetric[i],
               hann_symmetric_q15[i], d);
      mismatches++;
    }
    if (rt_hann_periodic[i] != hann_periodic_q15[i]) {
      int d = (int)rt_hann_periodic[i] - (int)hann_periodic_q15[i];
      if (d < 0) d = -d;
      if (d > max_delta) max_delta = d;
      if (mismatches < 5)
        printf("per[%d]: rt=%d gen=%d (delta %d)\n", i, rt_hann_periodic[i],
               hann_periodic_q15[i], d);
      mismatches++;
    }
  }

  printf("\n结果: %d 处不一致, 最大 delta = %d LSB\n", mismatches, max_delta);
  return mismatches ? 1 : 0;
}

